stdout:
# Edge gateway configuration.
http {
    limit_req_zone $binary_remote_addr zone=api:10m rate=100r/m;

    server {
        listen 443 ssl;
        server_name api.northwind.test;

        location / {
            limit_req zone=api burst=20 nodelay;
            proxy_pass http://upstream_app;
        }
    }
}

